import{describe,it,expect}from"vitest";import{SEASONS_DATA,CROPS_DATA,IRRIGATION_METHODS,validateFarmingCycleData,filterCropsBySeason,calculateCalendarRotationAngle}from"../../frontend/monsoon-farming-cycle/script.js";describe("Monsoon Farming Cycle Dataset Integrity (#581)",()=>{it("contains Kharif, Rabi, and Zaid agricultural seasons",()=>{expect(SEASONS_DATA).toHaveProperty("kharif"),expect(SEASONS_DATA).toHaveProperty("rabi"),expect(SEASONS_DATA).toHaveProperty("zaid")}),it("represents at least 6 crops with verified season data",()=>{expect(Array.isArray(CROPS_DATA)).toBe(!0),expect(CROPS_DATA.length).toBeGreaterThanOrEqual(6)}),it("validates crop dataset field structure",()=>{const e=validateFarmingCycleData(CROPS_DATA,SEASONS_DATA);expect(e.isValid).toBe(!0),expect(e.errors).toEqual([])}),it("ensures every crop has sowing/harvest timing, rainfall, and major states",()=>{CROPS_DATA.forEach(e=>{expect(e).toHaveProperty("name"),expect(e).toHaveProperty("sowing"),expect(e).toHaveProperty("harvest"),expect(e).toHaveProperty("rainfallReq"),expect(e).toHaveProperty("majorStates"),expect(e.majorStates.length).toBeGreaterThan(0)})})}),describe("Crop Filtering & Rotation Math",()=>{it("filters crops accurately by season key",()=>{const e=filterCropsBySeason("kharif");expect(e.length).toBeGreaterThan(0),e.forEach(e=>expect(e.season).toBe("kharif"));const t=filterCropsBySeason("rabi");expect(t.length).toBeGreaterThan(0),t.forEach(e=>expect(e.season).toBe("rabi"))}),it('returns all crops when filter is "all" or missing',()=>{const e=filterCropsBySeason("all");expect(e.length).toBe(CROPS_DATA.length)}),it("calculates calendar wheel rotation angle for month indices (0-11)",()=>{expect(calculateCalendarRotationAngle(0)).toBe(0),expect(calculateCalendarRotationAngle(6)).toBe(180),expect(calculateCalendarRotationAngle(3)).toBe(90)}),it("clamps rotation angles for out of bounds month indices",()=>{expect(calculateCalendarRotationAngle(-2)).toBe(0),expect(calculateCalendarRotationAngle(15)).toBe(330)})});